  critical: 'within_24_hours',
  high: 'within_3_days',
  medium: 'within_1_week',
  low: 'within_2_weeks',
};

function priorityBand(score) {
  if (score >= 80) return 'critical';
  if (score >= 60) return 'high';
  if (score >= 35) return 'medium';
  return 'low';
}

const lowered = routerReasons.map(r => String(r).toLowerCase());
const hasEvidenceConflict = lowered.some(r => r.indexOf('evidence_conflict') !== -1 || r.indexOf('evidence conflict') !== -1);
const humanReviewMarkers = ['human_review', 'human review', 'confidence_below', 'missing_historical_call_citations', 'missing_citations', 'not_parseable'];
const hasHumanReviewReason = lowered.some(r => humanReviewMarkers.some(m => r.indexOf(m) !== -1));

const perf = Number.isInteger(analysis.agent_performance_score) ? analysis.agent_performance_score : null;
const lead = Number.isInteger(analysis.lead_quality_score) ? analysis.lead_quality_score : null;
const conf = typeof analysis.confidence === 'number' ? analysis.confidence : null;
const risk = analysis.risk_level || null;
const outcome = analysis.call_outcome || null;
const sentiment = analysis.customer_sentiment || null;

let category = 'low_priority';
let reasonText = null;

if (hasEvidenceConflict) {
  category = 'evidence_conflict';
  reasonText = "The pipeline's evidence sources disagree on this call; a human must reconcile them.";
} else if (guardrailStatus === 'human_review_required' || hasHumanReviewReason) {
  category = 'human_review';
  reasonText = 'Routing sent this call to human review before the result can be trusted.';
} else if (perf !== null && perf <= 2) {
  category = 'critical_coaching';
  reasonText = 'Agent performance scored ' + perf + '/5 on this call; coaching is warranted.';
} else if (sentiment === 'negative') {
  category = 'customer_dissatisfaction';
  reasonText = 'Customer sentiment on this call was negative.';
} else if (lead !== null && lead >= 4 && outcome !== 'Sale') {
  category = 'recoverable_opportunity';
  reasonText = 'Lead quality scored ' + lead + '/5 but the call did not close; the opportunity looks recoverable.';
}

let attention;
if (category === 'low_priority') {
  attention = { required: false, priority: 'low', priority_score: 0, category: 'low_priority', reason: null };
} else {
  let score = CATEGORY_BASE[category];
  if (lead === 5) score += 15; else if (lead === 4) score += 10;
  if (perf !== null && perf <= 2) score += 10;
  if (risk === 'High') score += 10; else if (risk === 'Medium') score += 5;
  if (conf !== null && conf < 0.65) score += 8;
  if (outcome === 'Follow-up Needed') score += 5;
  score = Math.max(0, Math.min(100, score));
  attention = { required: true, priority: priorityBand(score), priority_score: score, category: category, reason: reasonText };
}

const recoveryDetected = lead !== null && lead >= 4 && outcome !== null && outcome !== 'Sale';
let recoveryOpportunity;
if (recoveryDetected) {
  const objectionKey = String(analysis.main_objection || '').trim().toLowerCase();
  const objectionPhrase = (objectionKey && objectionKey !== 'none') ? objectionKey : 'no explicit objection';
  recoveryOpportunity = {
    detected: true,
    confidence: conf,
    reason: 'Lead quality ' + lead + "/5 with outcome '" + outcome + "' and " + objectionPhrase + ' recorded as the main objection.',
    recommended_offer: OFFER_BY_OBJECTION[objectionKey] || DEFAULT_OFFER,
    recommended_follow_up_window: WINDOW_BY_PRIORITY[attention.priority],
  };
} else {
  recoveryOpportunity = { detected: false, confidence: null, reason: null, recommended_offer: null, recommended_follow_up_window: null };
}

// ---- assemble the response envelope -------------------------------------
const enrichedAnalysis = Object.assign({}, analysis, {
  guardrail_status: guardrailStatus,
  attention: attention,
  recovery_opportunity: recoveryOpportunity,
});
if (guardrailStatus === 'human_review_required' && (!enrichedAnalysis.routing_category || enrichedAnalysis.routing_category === 'uncategorized')) {
  enrichedAnalysis.routing_category = 'human_review_required';
}

const status = guardrailStatus === 'human_review_required'
  ? 'human_review_required'
  : (guardrailStatus === 'flagged' ? 'flagged' : 'completed');

const createdAt = new Date().toISOString();
const callDate = (ctx.submission_call_date && String(ctx.submission_call_date).trim())
  ? String(ctx.submission_call_date).trim()
  : createdAt.slice(0, 10);

const finalOutput = {
  call_id: ctx.call_id,
  created_at: createdAt,
  call_date: callDate,
  agent_name: String(ctx.submission_agent_name || '').trim(),
  customer_name: (ctx.submission_customer_name && String(ctx.submission_customer_name).trim()) ? String(ctx.submission_customer_name).trim() : null,
  status: status,
  router_reasons: routerReasons,
  analysis: enrichedAnalysis,
};

return [{ json: { final_output: finalOutput, router_reasons: routerReasons } }];

// The user-facing response. Always returns the Router's envelope, whether or
// not persistence succeeded -- a storage problem must never cost the user
// their analysis. `persistence` reports what actually happened, without
// leaking any storage internals (bucket, key, AWS error codes).
const routerOut = $('Router - Confidence and Category').item.json.final_output;
const raw = $json || {};

let persisted = false;
let detail = 'Call data service did not confirm the write.';
if (raw && raw.call_id && (raw.created === true || raw.overwritten === true)) {
  persisted = true;
  detail = raw.overwritten ? 'Existing record updated.' : 'Record stored.';
} else if (raw && raw.error) {
  detail = 'Call data service was unreachable; this analysis was returned but not stored.';
}

const finalOutput = Object.assign({}, routerOut, {
  persistence: { persisted: persisted, detail: detail },
});

return [{ json: finalOutput }];

const e = $json._pipeline_error || {};
let startedAt = null;
try { startedAt = $('Capture Start Time').item.json.started_at_ms; } catch (err) { startedAt = null; }
return [{
  json: {
    http_status: e.http_status || 500,
    response: {
      status: 'error',
      stage: e.stage || 'pipeline',
      error_code: e.error_code || 'pipeline_error',
      message: e.message || 'An error occurred later in the analysis pipeline.',
      processing_time_ms: startedAt ? ($now.toMillis() - startedAt) : null,
      workflow_version: 'phase9-16-full-pipeline'
    },
    debug_error: e.debug_error || e.message || 'unknown'
  }
}];

function iso(ms) {
  return (typeof ms === 'number') ? new Date(ms).toISOString() : new Date().toISOString();
}
function stageEvent(executionId, stage, provider, service, opts) {
  opts = opts || {};
  const startedMs = opts.startedMs;
  const completedMs = opts.completedMs;
  return {
    idempotency_key: executionId + ':' + stage,
    provider: provider,
    service: service,
    model: opts.model || null,
    pipeline_stage: stage,
    use_case: 'analyze_sales_call',
    input_tokens: (opts.inputTokens !== undefined && opts.inputTokens !== null) ? opts.inputTokens : null,
    output_tokens: (opts.outputTokens !== undefined && opts.outputTokens !== null) ? opts.outputTokens : null,
    audio_duration_seconds: (opts.audioDurationSeconds !== undefined && opts.audioDurationSeconds !== null) ? opts.audioDurationSeconds : null,
    request_count: 1,
    latency_ms: (typeof startedMs === 'number' && typeof completedMs === 'number') ? (completedMs - startedMs) : null,
    status: opts.status || 'success',
    occurred_at: iso(completedMs),
    metadata: {},
  };
}

const executionId = $execution.id;
const captureStart = $('Capture Start Time').item.json;
const callId = captureStart.call_id;  // canonical CALL_<uuid4>, not $execution.id
const pipelineStartedMs = captureStart.started_at_ms;

let transcriptionNode = null;
try { transcriptionNode = $('Normalize Transcript').item.json; } catch (e) {}
const transcription = (transcriptionNode && transcriptionNode.transcription) || {};
const transcriptionCompletedMs = transcriptionNode ? transcriptionNode.transcription_completed_at_ms : null;
const audioDurationSeconds = (typeof transcription.duration_ms === 'number') ? transcription.duration_ms / 1000 : null;

let extractionNode = null;
try { extractionNode = $('Parse Gemini Extraction').item.json; } catch (e) {}
let infoExtractionStartedMs = null;
try { infoExtractionStartedMs = $('Post-Transcription Content Check').item.json.information_extraction_started_at_ms; } catch (e) {}

let prepareDownstreamNode = null;
try { prepareDownstreamNode = $('Prepare Downstream Payloads').item.json; } catch (e) {}
const parallelCallsStartedMs = prepareDownstreamNode ? prepareDownstreamNode.parallel_calls_started_at_ms : null;

let ragMergeNode = null;
try { ragMergeNode = $('Prepare RAG For Merge').item.json; } catch (e) {}
const ragCompletedMs = ragMergeNode ? ragMergeNode.rag_retrieval_completed_at_ms : null;

let signalMergeNode = null;
try { signalMergeNode = $('Prepare Signal For Merge').item.json; } catch (e) {}
const signalCompletedMs = signalMergeNode ? signalMergeNode.call_signal_analysis_completed_at_ms : null;

let langgraphPayloadNode = null;
try { langgraphPayloadNode = $('Prepare LangGraph Payload').item.json; } catch (e) {}
const langgraphStartedMs = langgraphPayloadNode ? langgraphPayloadNode.langgraph_reasoning_started_at_ms : null;

let assembleContextNode = null;
try { assembleContextNode = $('Assemble Final Analysis Context').item.json; } catch (e) {}
const langgraphCompletedMs = assembleContextNode ? assembleContextNode.langgraph_reasoning_completed_at_ms : null;
const finalAnalysisStartedMs = assembleContextNode ? assembleContextNode.final_analysis_started_at_ms : null;

let parseFinalNode = null;
try { parseFinalNode = $('Parse Final Analysis Output').item.json; } catch (e) {}
const finalAnalysisCompletedMs = parseFinalNode ? parseFinalNode.final_analysis_completed_at_ms : null;

const infoExtractionUsage = (extractionNode && extractionNode.information_extraction_usage) || {};
const finalAnalysisUsage = (parseFinalNode && parseFinalNode.final_analysis_usage) || {};

const finalOutput = $json.final_output || {};

const events = [
  stageEvent(executionId, 'transcription', 'assemblyai', 'transcription', {
    startedMs: pipelineStartedMs, completedMs: transcriptionCompletedMs,
    model: transcription.speech_model || null,
    audioDurationSeconds: audioDurationSeconds,
    status: (transcription.status === 'completed') ? 'success' : 'partial',
  }),
  stageEvent(executionId, 'information_extraction', 'gemini', 'generative_ai', {
    startedMs: infoExtractionStartedMs, completedMs: extractionNode ? extractionNode.information_extraction_completed_at_ms : null,
    model: 'gemini-3.5-flash',
    inputTokens: infoExtractionUsage.input_tokens, outputTokens: infoExtractionUsage.output_tokens,
    status: (extractionNode && extractionNode.extraction_parse_error) ? 'partial' : 'success',
  }),
  stageEvent(executionId, 'rag_retrieval', 'internal', 'rag_service', {
    startedMs: parallelCallsStartedMs, completedMs: ragCompletedMs,
  }),
  stageEvent(executionId, 'call_signal_analysis', 'internal', 'call_signal_analyser', {
    startedMs: parallelCallsStartedMs, completedMs: signalCompletedMs,
  }),
  stageEvent(executionId, 'langgraph_reasoning', 'internal', 'langgraph_agent', {
    startedMs: langgraphStartedMs, completedMs: langgraphCompletedMs,
  }),
  stageEvent(executionId, 'final_analysis', 'gemini', 'generative_ai', {
    startedMs: finalAnalysisStartedMs, completedMs: finalAnalysisCompletedMs,
    model: 'gemini-3.5-flash',
    inputTokens: finalAnalysisUsage.input_tokens, outputTokens: finalAnalysisUsage.output_tokens,
    status: (parseFinalNode && parseFinalNode.final_analysis_parse_error) ? 'partial' : 'success',
  }),
];

const observability_payload = {
  call_id: callId,
  workflow_execution_id: executionId,
  trace_metadata: {
    environment: 'production',
    final_status: (finalOutput.analysis && finalOutput.analysis.guardrail_status) || 'unknown',
    use_case: 'analyze_sales_call',
  },
  events: events,
};

return [{ json: { ...$json, observability_payload } }];

// Maps the Router's envelope onto call_data_service's POST /calls contract.
// Reads the Router node directly, NOT $json: the upstream
// 'Build Success Response - Full Analysis' Set node runs in raw mode and has
// already unwrapped the envelope down to the bare analysis object, so
// $json.final_output does not exist at this point.
// status / created_at / attention / recovery_opportunity are intentionally
// omitted -- call_data_service derives them from the same inputs on write.

function uuid4() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  const hex = '0123456789abcdef';
  let s = '';
  for (let i = 0; i < 36; i++) {
    if (i === 8 || i === 13 || i === 18 || i === 23) s += '-';
    else if (i === 14) s += '4';
    else if (i === 19) s += hex[(Math.floor(Math.random() * 16) & 0x3) | 0x8];
    else s += hex[Math.floor(Math.random() * 16)];
  }
  return s;
}

const router = $('Router - Confidence and Category').first().json;
const body = $('Webhook Trigger').first().json.body || {};

return [{
  json: {
    persistence_payload: {
      schema_version: '1.0',
      call_id: 'CALL_' + uuid4(),
      source: 'live_analysis',
      call_date: body.call_date,
      agent_name: body.agent_name || 'Unknown Agent',
      customer_name: body.customer_name,
      router_reasons: router.router_reasons || [],
      analysis: router.final_output,
    },
  },
}];
